/**
 * Phonos Application - Main JavaScript
 * Modern, modular dashboard application
 */

// Utility: debounce - limits function calls to once per delay
function debounce(fn, delay = 300) {
    let timer;
    return function (...args) {
        clearTimeout(timer);
        timer = setTimeout(() => fn.apply(this, args), delay);
    };
}

// Utility: throttle - ensures function is called at most once per interval
function throttle(fn, interval = 200) {
    let lastTime = 0;
    return function (...args) {
        const now = Date.now();
        if (now - lastTime >= interval) {
            lastTime = now;
            fn.apply(this, args);
        }
    };
}

// Security: HTML escape function to prevent XSS
function escapeHtml(text) {
    if (typeof text !== 'string') return text;
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

/**
 * Get the real filename for extension matching.
 * Job artifacts have display names (e.g. "Full Sequence (FASTA)") in f.filename
 * but the actual filename (e.g. "job123_full.fasta") in f.artifact_filename.
 */
function fileRealName(f) {
    return f.artifact_filename || f.filename || '';
}

/**
 * Get the file content from the appropriate API endpoint.
 * Artifact IDs are compound strings "jobId:artifactFilename", regular file IDs are integers.
 */
async function fetchFileContent(fileId) {
    if (typeof fileId === 'string' && fileId.includes(':')) {
        const [jobId, artifactName] = fileId.split(':', 2);
        return API.get(`/api/jobs/${encodeURIComponent(jobId)}/artifacts/${encodeURIComponent(artifactName)}/content`);
    }
    return API.get(`/api/files/${fileId}/content`);
}

// Escape text for use in JavaScript string literals (e.g., in onclick handlers)
function escapeJs(text) {
    if (typeof text !== 'string') return text;
    // Escape backslashes, quotes, newlines, tabs, and other control characters
    return text.replace(/\\/g, '\\\\')
        .replace(/'/g, "\\'")
        .replace(/"/g, '\\"')
        .replace(/\n/g, '\\n')
        .replace(/\r/g, '\\r')
        .replace(/\t/g, '\\t')
        .replace(/\f/g, '\\f')
        .replace(/\v/g, '\\v')
        .replace(/\u2028/g, '\\u2028')
        .replace(/\u2029/g, '\\u2029');
}

/**
 * Device Detection and Mobile Utilities
 * Used for responsive behavior and hiding features on mobile
 */
const DeviceUtils = {
    // Breakpoints (matching CSS)
    BREAKPOINT_XS: 380,
    BREAKPOINT_SM: 480,
    BREAKPOINT_MD: 768,
    BREAKPOINT_LG: 1024,
    BREAKPOINT_XL: 1280,

    // Features to hide on mobile
    mobileHiddenFeatures: ['flows', 'flow-builder'],

    // Check if device is mobile (screen width based)
    isMobile() {
        return window.innerWidth <= this.BREAKPOINT_MD;
    },

    // Check if device is tablet
    isTablet() {
        return window.innerWidth > this.BREAKPOINT_MD && window.innerWidth <= this.BREAKPOINT_LG;
    },

    // Check if touch device
    isTouchDevice() {
        return 'ontouchstart' in window ||
               navigator.maxTouchPoints > 0 ||
               navigator.msMaxTouchPoints > 0;
    },

    // Get device type
    getDeviceType() {
        if (this.isMobile()) return 'mobile';
        if (this.isTablet()) return 'tablet';
        return 'desktop';
    },

    // Check if feature should be hidden on current device
    shouldHideOnMobile(featureName) {
        return this.isMobile() && this.mobileHiddenFeatures.includes(featureName);
    },

    // Add resize listener with debounce
    onResize(callback, debounceMs = 150) {
        let timeout;
        window.addEventListener('resize', () => {
            clearTimeout(timeout);
            timeout = setTimeout(callback, debounceMs);
        });
    },

    // Set body class based on device type
    setDeviceClass() {
        const body = document.body;
        body.classList.remove('device-mobile', 'device-tablet', 'device-desktop');
        body.classList.add(`device-${this.getDeviceType()}`);

        if (this.isTouchDevice()) {
            body.classList.add('touch-device');
        } else {
            body.classList.remove('touch-device');
        }
    },

    // Initialize device detection
    init() {
        this.setDeviceClass();
        this.onResize(() => {
            this.setDeviceClass();
            this.updateNavigationVisibility();
        });
        // Initial navigation update
        this.updateNavigationVisibility();
    },

    // Update navigation visibility based on device
    updateNavigationVisibility() {
        // Placeholder for device-specific navigation updates
    }
};

// Initialize DeviceUtils on DOM ready
document.addEventListener('DOMContentLoaded', () => {
    DeviceUtils.init();
});

/**
 * Header Manager
 * Handles header features: search, connection status, quick actions, theme toggle
 */
const HeaderManager = {
    searchTimeout: null,

    init() {
        this.setupGlobalSearch();
        this.setupQuickActions();
        this.setupThemeToggle();
        this.setupKeyboardShortcuts();
    },

    setupGlobalSearch() {
        const searchInput = document.getElementById('global-search');
        if (!searchInput) return;

        searchInput.addEventListener('input', (e) => {
            clearTimeout(this.searchTimeout);
            this.searchTimeout = setTimeout(() => {
                const query = e.target.value.trim();
                if (query.length >= 2) {
                    this.performGlobalSearch(query);
                }
            }, 300);
        });

        searchInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                clearTimeout(this.searchTimeout);
                const query = e.target.value.trim();
                if (query.length >= 2) {
                    this.performGlobalSearch(query);
                }
            } else if (e.key === 'Escape') {
                searchInput.value = '';
                searchInput.blur();
            }
        });

        // Focus on Ctrl+K
        searchInput.addEventListener('focus', () => {
            searchInput.select();
        });
    },

    async performGlobalSearch(query) {
        let resultsContainer = document.getElementById('global-search-results');
        if (!resultsContainer) {
            const searchContainer = document.querySelector('.header-search-wrapper');
            if (searchContainer) {
                resultsContainer = document.createElement('div');
                resultsContainer.id = 'global-search-results';
                resultsContainer.className = 'search-results-dropdown';
                searchContainer.appendChild(resultsContainer);
            }
        }

        if (!resultsContainer) return;

        resultsContainer.innerHTML = '<div class="search-loading">Searching...</div>';
        resultsContainer.style.display = 'block';

        try {
            const response = await fetch(`/api/search/global?q=${encodeURIComponent(query)}`);
            if (!response.ok) throw new Error('Search failed');
            const results = await response.json();

            if (results.length === 0) {
                resultsContainer.innerHTML = '<div class="search-no-results">No results found</div>';
                return;
            }

            resultsContainer.innerHTML = results.map(item => `
                <div class="search-result-item" data-type="${item.type}" data-id="${item.id}">
                    <div class="search-result-icon">${this.getSearchResultIcon(item.type)}</div>
                    <div class="search-result-content">
                        <div class="search-result-title">${this.escapeHtml(item.title)}</div>
                        <div class="search-result-meta">${this.escapeHtml(item.meta || item.type)}</div>
                    </div>
                </div>
            `).join('');

            resultsContainer.querySelectorAll('.search-result-item').forEach(item => {
                item.addEventListener('click', () => {
                    const type = item.dataset.type;
                    const id = item.dataset.id;
                    this.handleSearchResultClick(type, id);
                    resultsContainer.style.display = 'none';
                    document.getElementById('global-search').value = '';
                });
            });
        } catch (error) {
            console.error('Search error:', error);
            resultsContainer.innerHTML = '<div class="search-error">Search failed. Try again.</div>';
        }
    },

    getSearchResultIcon(type) {
        const icons = {
            'job': '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>',
            'file': '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>',
            'project': '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>',
            'notebook': '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg>',
            'flow': '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>'
        };
        return icons[type] || '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>';
    },

    handleSearchResultClick(type, id) {
        const routes = {
            'job': `/jobs?id=${id}`,
            'file': `/files?id=${id}`,
            'project': `/projects/${id}`,
            'notebook': `/notebook?id=${id}`,
            'flow': `/flows/${id}`
        };
        if (routes[type]) {
            window.location.href = routes[type];
        }
    },

    escapeHtml(text) {
        if (!text) return '';
        return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    },

    setupQuickActions() {
        // Quick New Job button
        const newJobBtn = document.getElementById('quick-new-job');
        if (newJobBtn) {
            newJobBtn.addEventListener('click', () => {
                if (typeof Views !== 'undefined' && Views.load) {
                    Views.load('submit-job');
                }
            });
        }

        // Quick Refresh button
        const refreshBtn = document.getElementById('quick-refresh');
        if (refreshBtn) {
            refreshBtn.addEventListener('click', () => {
                if (typeof Views !== 'undefined' && Views.load) {
                    Views.load(Views.current);
                    // Add spin animation
                    refreshBtn.style.animation = 'spin 0.5s ease';
                    setTimeout(() => {
                        refreshBtn.style.animation = '';
                    }, 500);
                }
                if (typeof Toast !== 'undefined') {
                    Toast.info('Refreshing...');
                }
            });
        }
    },

    setupThemeToggle() {
        // Force dark mode — no toggle
    },

    updateThemeIcons(theme, sunIcon, moonIcon) {
        if (!sunIcon || !moonIcon) return;
        if (theme === 'dark') {
            sunIcon.style.display = 'block';
            moonIcon.style.display = 'none';
        } else {
            sunIcon.style.display = 'none';
            moonIcon.style.display = 'block';
        }
    },

    setupKeyboardShortcuts() {
        // Click outside to close search dropdown (registered once)
        document.addEventListener('click', (e) => {
            const resultsDropdown = document.getElementById('global-search-results');
            const searchWrapper = document.querySelector('.header-search-wrapper');
            if (resultsDropdown && searchWrapper && !searchWrapper.contains(e.target)) {
                resultsDropdown.style.display = 'none';
            }
        });

        // Close re-run dropdowns on any outside click. Registered in the
        // capture phase so inner handlers that call stopPropagation() (rows,
        // action buttons) can't swallow the click and leave the menu open.
        document.addEventListener('click', (e) => {
            if (!e.target.closest('.rerun-dropdown-wrap') && !e.target.closest('.rerun-dropdown-menu')) {
                App._closeAllRerunMenus();
            }
        }, true);
        // The menu is portaled to <body> with position:fixed, so close it on
        // scroll/resize instead of letting it float out of place.
        window.addEventListener('scroll', () => App._closeAllRerunMenus(), true);
        window.addEventListener('resize', () => App._closeAllRerunMenus());

        document.addEventListener('keydown', (e) => {
            // "/" or Ctrl+K for global search (when not in input)
            const isInputFocused = document.activeElement.tagName === 'INPUT' ||
                                   document.activeElement.tagName === 'TEXTAREA' ||
                                   document.activeElement.isContentEditable;

            if (e.key === '/' && !isInputFocused) {
                e.preventDefault();
                const searchInput = document.getElementById('global-search');
                if (searchInput) {
                    searchInput.focus();
                }
            }

            if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
                e.preventDefault();
                const searchInput = document.getElementById('global-search');
                if (searchInput) {
                    searchInput.focus();
                }
            }

            // Escape to close search dropdown
            if (e.key === 'Escape') {
                const resultsDropdown = document.getElementById('global-search-results');
                if (resultsDropdown) {
                    resultsDropdown.style.display = 'none';
                }
            }

            // Ctrl+N for new job (delegates to Views.load)
            if ((e.ctrlKey || e.metaKey) && e.key === 'n' && !e.shiftKey && !isInputFocused) {
                e.preventDefault();
                if (typeof Views !== 'undefined' && Views.load) {
                    Views.load('submit-job');
                }
            }
        });
    },

    // Update notification badge
    updateNotificationCount(count) {
        const badge = document.getElementById('notification-count');
        if (!badge) return;

        if (count > 0) {
            badge.textContent = count > 99 ? '99+' : count;
            badge.style.display = 'flex';
        } else {
            badge.style.display = 'none';
        }
    }
};

// Initialize HeaderManager on DOM ready
document.addEventListener('DOMContentLoaded', () => {
    HeaderManager.init();
});

/**
 * Breadcrumb Navigation Manager
 * Tracks navigation path and provides breadcrumb UI
 */
const BreadcrumbManager = {
    // Navigation history stack
    history: [],
    maxHistory: 10,

    // View name to display label mapping
    labels: {
        'dashboard': 'Dashboard',
        'projects': 'Projects',
        'project': 'Project',
        'files': 'Files',
        'jobs': 'Jobs',
        'submit-job': 'Submit Job',
        'batch': 'Batch',
        'viewer': '3D Viewer',
        'teams': 'Teams',
        'admin': 'Admin',
        'settings': 'Settings',
        'api-tokens': 'API Tokens',
        'api-docs': 'API Docs',
        'usage': 'Usage',
        'search': 'Search',
        'preview': 'Preview',
        'visualizer': 'Visualizer',
        'user-models': 'Custom Models',
        'user-model-builder': 'Model Builder',
        'bunches': 'Batch Jobs',
        'flows': 'Flows',
        'databases': 'Databases',
        'notebook': 'Notebook'
    },

    // Current context (e.g., project name)
    context: {},

    init() {
        // Start with dashboard
        this.history = [{ view: 'dashboard', label: 'Dashboard', context: {} }];
        this.render();

        // Handle browser back/forward
        window.addEventListener('popstate', (e) => {
            if (e.state && e.state.view) {
                this.navigateToHistoryIndex(e.state.index, false);
            }
        });
    },

    // Create SVG icon element
    createIcon(viewName) {
        const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        svg.setAttribute('width', '14');
        svg.setAttribute('height', '14');
        svg.setAttribute('viewBox', '0 0 24 24');
        svg.setAttribute('fill', 'none');
        svg.setAttribute('stroke', 'currentColor');
        svg.setAttribute('stroke-width', '2');

        const icons = {
            'dashboard': '<rect x="3" y="3" width="7" height="9"/><rect x="14" y="3" width="7" height="5"/><rect x="14" y="12" width="7" height="9"/><rect x="3" y="16" width="7" height="5"/>',
            'projects': '<path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/>',
            'files': '<path d="M13 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"/><polyline points="13 2 13 9 20 9"/>',
            'jobs': '<polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/>',
            'search': '<circle cx="11" cy="11" r="8"/><path d="M21 21l-4.35-4.35"/>',
            'settings': '<circle cx="12" cy="12" r="3"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/>'
        };

        // Use a template element for safe parsing of static SVG paths
        if (icons[viewName]) {
            const template = document.createElement('template');
            template.innerHTML = icons[viewName];
            Array.from(template.content.childNodes).forEach(node => {
                if (node.nodeType === 1) {
                    const clone = document.createElementNS('http://www.w3.org/2000/svg', node.tagName);
                    Array.from(node.attributes).forEach(attr => clone.setAttribute(attr.name, attr.value));
                    svg.appendChild(clone);
                }
            });
        }
        return svg;
    },

    // Update breadcrumbs when view changes
    update(viewName, options = {}) {
        const label = options.label || this.labels[viewName] || viewName;
        const context = options.context || {};

        // Check if navigating back to an existing item
        const existingIndex = this.history.findIndex(item =>
            item.view === viewName && JSON.stringify(item.context) === JSON.stringify(context)
        );

        if (existingIndex !== -1) {
            // Truncate history to this point
            this.history = this.history.slice(0, existingIndex + 1);
        } else {
            // Add new item
            this.history.push({ view: viewName, label, context });

            // Keep history manageable
            if (this.history.length > this.maxHistory) {
                this.history.shift();
            }
        }

        // Update URL hash
        this.updateUrlHash(viewName, context);

        // Re-render breadcrumbs
        this.render();
    },

    // Set context for current view (e.g., project name)
    setContext(key, value) {
        this.context[key] = value;
        if (this.history.length > 0) {
            this.history[this.history.length - 1].context[key] = value;
            this.history[this.history.length - 1].label = value;
            this.render();
        }
    },

    // Navigate to a specific history index
    navigateToHistoryIndex(index, updateHistory = true) {
        if (index >= 0 && index < this.history.length) {
            const item = this.history[index];
            if (updateHistory) {
                this.history = this.history.slice(0, index + 1);
            }

            // Load the view
            if (typeof Views !== 'undefined') {
                Views.load(item.view, item.context);
            }
        }
    },

    // Go back one step
    goBack() {
        if (this.history.length > 1) {
            this.history.pop();
            const previous = this.history[this.history.length - 1];
            if (typeof Views !== 'undefined') {
                Views.load(previous.view, previous.context);
            }
        }
    },

    // Update URL hash for deep linking
    updateUrlHash(viewName, context = {}) {
        let hash = viewName;
        if (context.projectId) {
            hash += `/project/${context.projectId}`;
        }
        if (context.fileId) {
            hash += `/file/${context.fileId}`;
        }
        if (context.jobId) {
            hash += `/job/${context.jobId}`;
        }

        const newUrl = `${window.location.pathname}#${hash}`;
        window.history.pushState({ view: viewName, index: this.history.length - 1, context }, '', newUrl);
    },

    // Parse URL hash on page load
    parseUrlHash() {
        const hash = window.location.hash.slice(1);
        if (!hash) return null;

        const parts = hash.split('/');
        const viewName = parts[0];
        const context = {};

        for (let i = 1; i < parts.length; i += 2) {
            if (parts[i] === 'project' && parts[i + 1]) {
                context.projectId = parseInt(parts[i + 1]);
            } else if (parts[i] === 'file' && parts[i + 1]) {
                context.fileId = parseInt(parts[i + 1]);
            } else if (parts[i] === 'job' && parts[i + 1]) {
                context.jobId = parseInt(parts[i + 1]);
            }
        }

        return { view: viewName, context };
    },

    // Render breadcrumb UI using safe DOM methods
    render() {
        const container = document.getElementById('breadcrumb-nav');
        if (!container) return;

        // Don't show breadcrumbs if only dashboard
        if (this.history.length <= 1 && this.history[0]?.view === 'dashboard') {
            container.style.display = 'none';
            return;
        }

        container.style.display = 'flex';
        container.textContent = ''; // Clear container safely

        // Create back button
        const backBtn = document.createElement('button');
        backBtn.className = 'breadcrumb-back';
        backBtn.id = 'breadcrumb-back-btn';
        backBtn.title = window.i18n ? window.i18n.t('app.goBack') : 'Go back';
        backBtn.disabled = this.history.length <= 1;

        const backSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        backSvg.setAttribute('width', '16');
        backSvg.setAttribute('height', '16');
        backSvg.setAttribute('viewBox', '0 0 24 24');
        backSvg.setAttribute('fill', 'none');
        backSvg.setAttribute('stroke', 'currentColor');
        backSvg.setAttribute('stroke-width', '2');

        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        line.setAttribute('x1', '19');
        line.setAttribute('y1', '12');
        line.setAttribute('x2', '5');
        line.setAttribute('y2', '12');
        backSvg.appendChild(line);

        const polyline = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
        polyline.setAttribute('points', '12 19 5 12 12 5');
        backSvg.appendChild(polyline);

        backBtn.appendChild(backSvg);
        backBtn.addEventListener('click', () => this.goBack());
        container.appendChild(backBtn);

        // Create breadcrumb trail
        const nav = document.createElement('nav');
        nav.className = 'breadcrumb-trail';
        nav.setAttribute('aria-label', 'Breadcrumb');

        this.history.forEach((item, index) => {
            const isLast = index === this.history.length - 1;

            if (isLast) {
                const span = document.createElement('span');
                span.className = 'breadcrumb-item breadcrumb-current';
                span.appendChild(this.createIcon(item.view));
                const labelSpan = document.createElement('span');
                labelSpan.textContent = item.label;
                span.appendChild(labelSpan);
                nav.appendChild(span);
            } else {
                const btn = document.createElement('button');
                btn.className = 'breadcrumb-item breadcrumb-link';
                btn.dataset.index = index;
                btn.appendChild(this.createIcon(item.view));
                const labelSpan = document.createElement('span');
                labelSpan.textContent = item.label;
                btn.appendChild(labelSpan);
                btn.addEventListener('click', () => this.navigateToHistoryIndex(index));
                nav.appendChild(btn);

                // Add separator
                const sep = document.createElement('span');
                sep.className = 'breadcrumb-separator';
                const sepSvg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
                sepSvg.setAttribute('width', '12');
                sepSvg.setAttribute('height', '12');
                sepSvg.setAttribute('viewBox', '0 0 24 24');
                sepSvg.setAttribute('fill', 'none');
                sepSvg.setAttribute('stroke', 'currentColor');
                sepSvg.setAttribute('stroke-width', '2');
                const sepPolyline = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
                sepPolyline.setAttribute('points', '9 18 15 12 9 6');
                sepSvg.appendChild(sepPolyline);
                sep.appendChild(sepSvg);
                nav.appendChild(sep);
            }
        });

        container.appendChild(nav);
    }
};

// API Client with enhanced error handling
const API = {
    // In-memory cache for GET requests - avoids redundant API calls
    _cache: new Map(),
    _cacheTTL: 30000, // 30 seconds default TTL

    _getCacheKey(endpoint, options) {
        return `${endpoint}:${JSON.stringify(options?.headers || {})}`;
    },

    _getFromCache(endpoint, options, ignoreTTL = false) {
        const key = this._getCacheKey(endpoint, options);
        const entry = this._cache.get(key);
        if (!entry) return null;
        // On a 304 the server has confirmed our copy is still current, so an
        // expired entry is still valid to return (ignoreTTL).
        if (!ignoreTTL && Date.now() - entry.timestamp > this._cacheTTL) {
            this._cache.delete(key);
            return null;
        }
        return entry.data;
    },

    _setCache(endpoint, options, data) {
        const key = this._getCacheKey(endpoint, options);
        this._cache.set(key, { data, timestamp: Date.now() });
        // Evict oldest entries if cache exceeds 200 items
        if (this._cache.size > 200) {
            const oldest = this._cache.keys().next().value;
            if (oldest) this._cache.delete(oldest);
        }
    },

    invalidateCache(pattern) {
        if (!pattern) {
            this._cache.clear();
            return;
        }
        for (const key of this._cache.keys()) {
            if (key.startsWith(pattern)) {
                this._cache.delete(key);
            }
        }
    },

    async fetch(endpoint, options = {}) {
        const timeout = options.timeout || 30000;
        const silent = options.silent || false;
        const cacheTTL = options.cacheTTL !== undefined ? options.cacheTTL : this._cacheTTL;
        const skipCache = options.skipCache === true;

        // Return cached data for GET requests when available
        const isGet = !options.method || options.method === 'GET';
        if (isGet && !skipCache && cacheTTL > 0) {
            const cached = this._getFromCache(endpoint, options);
            if (cached) return cached;
        }

        const config = {
            headers: {
                'Content-Type': 'application/json',
                'X-CSRF-Token': window.PHONOS_CONFIG?.csrfToken || '',
                ...options.headers
            },
            ...options
        };

        // Remove custom options before passing to fetch
        delete config.silent;
        delete config.timeout;
        delete config.cacheTTL;
        delete config.skipCache;
        delete config._reload304;

        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), timeout);
        config.signal = controller.signal;

        try {
            const response = await fetch(endpoint, config);
            clearTimeout(timeoutId);

            // 304 Not Modified has an empty body by spec, but servers/proxies
            // keep the application/json Content-Type. Parsing that empty body
            // throws "Server returned invalid response". Treat it as "use the
            // copy we already have": serve the in-memory cached value, or force
            // a non-conditional reload so we actually get a fresh body back.
            if (response.status === 304) {
                const cached = this._getFromCache(endpoint, options, true);
                if (cached !== null && cached !== undefined) return cached;
                if (!options._reload304) {
                    return this.fetch(endpoint, { ...options, cache: 'reload', _reload304: true });
                }
            }

            let data;
            const contentType = response.headers.get('content-type');
            if (contentType && contentType.includes('application/json')) {
                try {
                    data = await response.json();
                } catch (parseError) {
                    if (!silent) console.error('Failed to parse JSON response:', parseError);
                    throw new Error('Server returned invalid response');
                }
            } else {
                const text = await response.text();
                if (!silent) console.error('Non-JSON response:', text.substring(0, 200));
                throw new Error(response.ok ? 'Unexpected response format' : `Server error: ${response.status}`);
            }

            if (!response.ok) {
                const error = new Error(data.error || data.message || 'Request failed');
                error.code = data.code || this._getErrorCodeFromStatus(response.status);
                error.suggestion = data.suggestion || this._getSuggestionForError(error.code, response.status);
                error.statusCode = response.status;
                throw error;
            }

            // A successful mutating request (POST/PUT/PATCH/DELETE) can change what
            // subsequent GETs return — drop the in-memory GET cache so the next read
            // fetches fresh data instead of a stale 30s snapshot. Fixes lists not
            // updating after delete/archive/create until a manual page refresh.
            if (!isGet) {
                this.invalidateCache();
            }

            // Cache successful GET responses
            if (isGet && cacheTTL > 0) {
                this._setCache(endpoint, options, data);
            }

            return data;
        } catch (error) {
            if (!silent) console.error('API Error:', error);

            if (error.name === 'AbortError') {
                const timeoutError = new Error('Request timed out. Please try again.');
                timeoutError.code = 'TIMEOUT';
                timeoutError.suggestion = 'Check your internet connection and try again. If the problem persists, the server may be experiencing high load.';
                throw timeoutError;
            }

            if (error.message === 'Failed to fetch' || error.message.includes('NetworkError')) {
                const networkError = new Error('Network error. Please check your connection.');
                networkError.code = 'NETWORK_ERROR';
                networkError.suggestion = 'Check your internet connection and try again.';
                throw networkError;
            }

            throw error;
        }
    },

    _getErrorCodeFromStatus(status) {
        const codeMap = {
            400: 'INVALID_INPUT',
            401: 'UNAUTHORIZED',
            402: 'INSUFFICIENT_CREDITS',
            403: 'FORBIDDEN',
            404: 'NOT_FOUND',
            429: 'RATE_LIMIT',
            500: 'SERVER_ERROR',
            503: 'SERVICE_UNAVAILABLE',
            507: 'STORAGE_FULL'
        };
        return codeMap[status] || 'UNKNOWN_ERROR';
    },

    _getSuggestionForError(code, status) {
        const suggestions = {
            'INVALID_INPUT': 'Please check your input and try again.',
            'UNAUTHORIZED': 'Your session may have expired. Please log in again.',
            'INSUFFICIENT_CREDITS': 'You need more credits to perform this action. Credits reset monthly.',
            'FORBIDDEN': 'You do not have permission to perform this action.',
            'NOT_FOUND': 'The requested resource was not found. It may have been deleted.',
            'RATE_LIMIT': 'You have made too many requests. Please wait a moment and try again.',
            'SERVER_ERROR': 'An internal server error occurred. Please try again in a few moments.',
            'SERVICE_UNAVAILABLE': 'The service is temporarily unavailable. Please try again later.',
            'STORAGE_FULL': 'Your storage is full. Delete some old files to free up space.',
            'TIMEOUT': 'The request took too long. Please try again.',
            'NETWORK_ERROR': 'Network error. Please check your internet connection.'
        };
        return suggestions[code] || 'An unexpected error occurred. Please try again or contact support if the problem persists.';
    },

    get(endpoint, options = {}) {
        return this.fetch(endpoint, options);
    },

    // Silent GET that doesn't log errors to console
    getSilent(endpoint) {
        return this.fetch(endpoint, { silent: true });
    },

    post(endpoint, data, options = {}) {
        return this.fetch(endpoint, {
            method: 'POST',
            body: JSON.stringify(data),
            ...options
        });
    },

    patch(endpoint, data, options = {}) {
        return this.fetch(endpoint, {
            method: 'PATCH',
            body: JSON.stringify(data),
            ...options
        });
    },

    put(endpoint, data, options = {}) {
        return this.fetch(endpoint, {
            method: 'PUT',
            body: JSON.stringify(data),
            ...options
        });
    },

    delete(endpoint, options = {}) {
        return this.fetch(endpoint, { method: 'DELETE', ...options });
    }
};

// UI Enhancement Utilities
const UIEnhancements = {
    // Button loading states
    setButtonLoading(button, loading = true, originalText = null) {
        if (!button) return;

        if (loading) {
            button.disabled = true;
            button.classList.add('btn-loading');
            if (originalText) {
                button.dataset.originalText = originalText;
            } else {
                button.dataset.originalText = button.textContent;
            }
            // Wrap text in span for fade effect
            const textSpan = button.querySelector('.btn-text');
            if (!textSpan) {
                button.innerHTML = `<span class="btn-text">${button.textContent}</span>`;
            }
        } else {
            button.disabled = false;
            button.classList.remove('btn-loading');
            if (button.dataset.originalText) {
                button.textContent = button.dataset.originalText;
                delete button.dataset.originalText;
            }
        }
    },

    // Form field validation
    validateField(field, validator) {
        const formGroup = field.closest('.form-group');
        if (!formGroup) return true;

        const errorEl = formGroup.querySelector('.form-error');
        const value = field.value.trim();

        // Run validator
        const result = validator(value, field);

        if (result.valid) {
            field.classList.remove('is-invalid');
            field.classList.add('is-valid');
            formGroup.classList.remove('is-invalid');
            formGroup.classList.add('is-valid');
            if (errorEl) {
                errorEl.classList.remove('is-visible');
            }
            return true;
        } else {
            field.classList.remove('is-valid');
            field.classList.add('is-invalid');
            formGroup.classList.remove('is-valid');
            formGroup.classList.add('is-invalid');
            if (errorEl) {
                errorEl.textContent = result.message || (window.i18n ? window.i18n.t('app.invalidInput') : 'Invalid input');
                errorEl.classList.add('is-visible');
            }
            return false;
        }
    },

    // Clear field validation
    clearFieldValidation(field) {
        const formGroup = field.closest('.form-group');
        if (!formGroup) return;

        field.classList.remove('is-invalid', 'is-valid');
        formGroup.classList.remove('is-invalid', 'is-valid');
        const errorEl = formGroup.querySelector('.form-error');
        if (errorEl) {
            errorEl.classList.remove('is-visible');
        }
    },

    // Common validators
    validators: {
        required: (value) => ({
            valid: value.length > 0,
            message: 'This field is required'
        }),
        email: (value) => ({
            valid: !value || /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value),
            message: 'Please enter a valid email address'
        }),
        minLength: (min) => (value) => ({
            valid: value.length >= min,
            message: `Must be at least ${min} characters`
        }),
        maxLength: (max) => (value) => ({
            valid: value.length <= max,
            message: `Must be no more than ${max} characters`
        }),
        sequence: (value) => {
            if (!value) return { valid: false, message: 'Sequence is required' };
            const validChars = /^[ACDEFGHIKLMNPQRSTVWY\s>]+$/i;
            if (!validChars.test(value)) {
                return { valid: false, message: 'Invalid amino acid characters' };
            }
            return { valid: true };
        }
    },

    // Enhanced error display with recovery suggestions
    showError(message, error = null, container = null) {
        const suggestion = error?.suggestion || 'Please try again or contact support.';

        const wrapper = document.createElement('div');
        wrapper.className = 'error-message';

        const titleDiv = document.createElement('div');
        titleDiv.className = 'error-message-title';
        titleDiv.textContent = message;
        wrapper.appendChild(titleDiv);

        if (suggestion) {
            const sugDiv = document.createElement('div');
            sugDiv.className = 'error-message-suggestion';
            sugDiv.textContent = suggestion;
            wrapper.appendChild(sugDiv);
        }

        if (container) {
            container.textContent = '';
            container.appendChild(wrapper);
        }
        return wrapper;
    },

    renderNotebookItem(notebook) {
        const clickHandler = `window.location.href = '/notebook?id=${notebook.id}'`;
        const activeBadge = notebook.active_sessions > 0 ?
            `<span class="fm-item-badge active">Active</span>` : '';
        const outputInfo = notebook.output_count > 0 ?
            `<span class="fm-item-meta-secondary">${notebook.output_count} output${notebook.output_count !== 1 ? 's' : ''}</span>` : '';

        return `
            <div class="fm-item fm-item-notebook" onclick="${clickHandler}">
                <div class="fm-item-icon notebook fm-icon-large">
                    <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
                        <path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/>
                        <path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/>
                    </svg>
                </div>
                <div class="fm-item-icon notebook fm-icon-small">
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/>
                        <path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/>
                    </svg>
                </div>
                <div class="fm-item-info">
                    <div class="fm-item-name">${escapeHtml(notebook.name)}${activeBadge}</div>
                    <div class="fm-item-meta">
                        By ${escapeHtml(notebook.creator_name || 'Unknown')}
                        ${notebook.cell_count ? `<span class="fm-item-meta-secondary">${notebook.cell_count} cell${notebook.cell_count !== 1 ? 's' : ''}</span>` : ''}
                        ${outputInfo}
                    </div>
                </div>
                <div class="fm-item-type">Notebook</div>
                <div class="fm-item-actions">
                    <button class="fm-action-btn" onclick="event.stopPropagation(); ${clickHandler}" title="Open">
                        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <path d="M5 12h14"/><path d="M12 5l7 7-7 7"/>
                        </svg>
                    </button>
                </div>
            </div>
        `;
    },

    renderDeviceItem(device) {
        const statusClass = device.is_online ? 'online' : 'offline';
        const statusLabel = device.is_online ? 'Online' : 'Offline';

        return `
            <div class="fm-item fm-item-device">
                <div class="fm-item-icon device fm-icon-large">
                    <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
                        <rect x="4" y="4" width="16" height="16" rx="2"/>
                        <rect x="9" y="9" width="6" height="6"/>
                        <line x1="9" y1="1" x2="9" y2="4"/>
                        <line x1="15" y1="1" x2="15" y2="4"/>
                        <line x1="9" y1="20" x2="9" y2="23"/>
                        <line x1="15" y1="20" x2="15" y2="23"/>
                    </svg>
                </div>
                <div class="fm-item-icon device fm-icon-small">
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <rect x="4" y="4" width="16" height="16" rx="2"/>
                        <rect x="9" y="9" width="6" height="6"/>
                    </svg>
                </div>
                <div class="fm-item-info">
                    <div class="fm-item-name">${escapeHtml(device.name)}</div>
                    <div class="fm-item-meta">${escapeHtml(device.device_type)}</div>
                </div>
                <div class="fm-item-type">${device.device_type}</div>
                <div class="fm-item-status ${statusClass}">${statusLabel}</div>
            </div>
        `;
    },

    renderNotebookFileItem(file) {
        const ext = file.filename.split('.').pop().toLowerCase();
        const isEditable = ['py', 'json', 'txt', 'md', 'csv', 'yaml', 'yml', 'xml'].includes(ext);

        const iconLarge = `
            <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
                <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/>
                <polyline points="14 2 14 8 20 8"/>
                <line x1="16" y1="13" x2="8" y2="13"/>
                <line x1="16" y1="17" x2="8" y2="17"/>
                <polyline points="10 9 9 9 8 9"/>
            </svg>
        `;

        const iconSmall = `
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/>
                <polyline points="14 2 14 8 20 8"/>
            </svg>
        `;

        const clickHandler = `App.openNotebookFile(${file.notebook_id}, '${escapeJs(file.file_path)}')`;
        const downloadHandler = `App.downloadNotebookFile(${file.notebook_id}, '${escapeJs(file.file_path)}')`;
        const size = file.size ? App.formatBytes(file.size) : '';

        return `
            <div class="fm-item fm-item-notebook-file" onclick="${clickHandler}">
                <div class="fm-item-icon notebook-file fm-icon-large">${iconLarge}</div>
                <div class="fm-item-icon notebook-file fm-icon-small">${iconSmall}</div>
                <div class="fm-item-info">
                    <div class="fm-item-name">${escapeHtml(file.filename)}</div>
                    <div class="fm-item-meta">${escapeHtml(file.notebook_name)}</div>
                </div>
                <div class="fm-item-type">.${ext.toUpperCase()}</div>
                <div class="fm-item-size">${size}</div>
                <div class="fm-item-actions">
                    <button class="fm-action-btn" onclick="event.stopPropagation(); ${clickHandler}" title="Open">
                        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/>
                            <circle cx="12" cy="12" r="3"/>
                        </svg>
                    </button>
                    <button class="fm-action-btn" onclick="event.stopPropagation(); ${downloadHandler}" title="Download">
                        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>
                            <polyline points="7 10 12 15 17 10"/>
                            <line x1="12" y1="15" x2="12" y2="3"/>
                        </svg>
                    </button>
                </div>
            </div>
        `;
    },

    // Empty state component
    renderEmptyState(container, options = {}) {
        const {
            icon = '📭',
            title = 'No items found',
            description = 'Get started by creating your first item',
            actions = []
        } = options;

        const actionsHTML = actions.map(action =>
            `<button class="btn btn-primary" onclick="${escapeHtml(action.onclick)}">${escapeHtml(action.text)}</button>`
        ).join('');

        const emptyStateHTML = `
            <div class="empty-state">
                <div class="empty-state-icon">${icon}</div>
                <h3 class="empty-state-title">${escapeHtml(title)}</h3>
                <p class="empty-state-description">${escapeHtml(description)}</p>
                ${actions.length > 0 ? `<div class="empty-state-actions">${actionsHTML}</div>` : ''}
            </div>
        `;

        if (container) {
            container.innerHTML = emptyStateHTML;
        }
        return emptyStateHTML;
    },

    // Progress indicator
    createProgressSteps(steps, currentStep = 0) {
        const stepsHTML = steps.map((step, index) => {
            const isActive = index === currentStep;
            const isCompleted = index < currentStep;
            const statusClass = isActive ? 'is-active' : (isCompleted ? 'is-completed' : '');

            return `
                <div class="progress-step ${statusClass}">
                    <div class="progress-step-circle">${isCompleted ? '✓' : index + 1}</div>
                    <div class="progress-step-label">${escapeHtml(step)}</div>
                </div>
            `;
        }).join('');

        return `<div class="progress-steps">${stepsHTML}</div>`;
    },

    // Button loading with custom text
    setButtonLoadingWithText(button, loading = true, loadingText = 'Loading...') {
        if (!button) return;

        if (loading) {
            button.dataset.originalHtml = button.innerHTML;
            button.disabled = true;
            button.classList.add('btn-loading-text');
            const span1 = document.createElement('span');
            span1.textContent = button.textContent;
            const span2 = document.createElement('span');
            span2.className = 'loading-label';
            span2.textContent = loadingText;
            button.textContent = '';
            button.appendChild(span1);
            button.appendChild(span2);
        } else {
            button.disabled = false;
            button.classList.remove('btn-loading-text');
            if (button.dataset.originalHtml) {
                button.innerHTML = button.dataset.originalHtml;
                delete button.dataset.originalHtml;
            }
        }
    },

    // Flash feedback on button (success/error)
    flashButton(button, type = 'success') {
        if (!button) return;
        const className = type === 'success' ? 'btn-success-flash' : 'btn-error-flash';
        button.classList.add(className);
        setTimeout(() => button.classList.remove(className), 600);
    },

    // Add page enter animation to element
    animatePageEnter(element) {
        if (!element) return;
        element.classList.add('page-enter');
        element.addEventListener('animationend', () => {
            element.classList.remove('page-enter');
        }, { once: true });
    },

    // Add slide in animation
    animateSlideIn(element, direction = 'up') {
        if (!element) return;
        const className = direction === 'up' ? 'slide-in-up' : 'slide-in-right';
        element.classList.add(className);
        element.addEventListener('animationend', () => {
            element.classList.remove(className);
        }, { once: true });
    },

    // Fade in element
    animateFadeIn(element) {
        if (!element) return;
        element.classList.add('fade-in');
        element.addEventListener('animationend', () => {
            element.classList.remove('fade-in');
        }, { once: true });
    },

    // Show loading overlay
    showLoadingOverlay(container, message = 'Loading...') {
        if (!container) return null;
        container.style.position = 'relative';

        const overlay = document.createElement('div');
        overlay.className = 'loading-overlay';

        const content = document.createElement('div');
        content.className = 'loading-overlay-content';

        const spinner = document.createElement('div');
        spinner.className = 'loading-spinner-large';

        const text = document.createElement('span');
        text.textContent = message;

        content.appendChild(spinner);
        content.appendChild(text);
        overlay.appendChild(content);
        container.appendChild(overlay);
        return overlay;
    },

    // Hide loading overlay
    hideLoadingOverlay(overlay) {
        if (!overlay) return;
        overlay.style.opacity = '0';
        setTimeout(() => overlay.remove(), 200);
    },

    // Create skeleton loading placeholder (returns safe HTML string)
    createSkeleton(type = 'text', count = 3) {
        const skeletons = {
            text: () => '<div class="skeleton skeleton-text"></div>',
            title: () => '<div class="skeleton skeleton-title"></div>',
            avatar: () => '<div class="skeleton skeleton-avatar"></div>',
            button: () => '<div class="skeleton skeleton-button"></div>',
            chart: () => '<div class="skeleton skeleton-chart"></div>',
            card: () => `
                <div class="skeleton-card">
                    <div class="skeleton-header">
                        <div class="skeleton skeleton-avatar"></div>
                        <div style="flex: 1;">
                            <div class="skeleton skeleton-text" style="width: 60%;"></div>
                            <div class="skeleton skeleton-text" style="width: 40%;"></div>
                        </div>
                    </div>
                    <div class="skeleton-body">
                        <div class="skeleton skeleton-text"></div>
                        <div class="skeleton skeleton-text"></div>
                        <div class="skeleton skeleton-text" style="width: 70%;"></div>
                    </div>
                </div>
            `,
            table: () => `
                <div class="skeleton-table-row">
                    <div class="skeleton"></div>
                    <div class="skeleton"></div>
                    <div class="skeleton"></div>
                    <div class="skeleton"></div>
                </div>
            `
        };

        const generator = skeletons[type] || skeletons.text;
        return Array(count).fill(0).map(() => generator()).join('');
    },

    // Show action feedback on element
    showActionFeedback(element, type = 'success') {
        if (!element) return;
        const className = type === 'success' ? 'action-success' : 'action-error';
        element.classList.add(className);
        setTimeout(() => element.classList.remove(className), 500);
    },

    // Add tooltip to element
    addTooltip(element, text) {
        if (!element) return;
        element.classList.add('tooltip');
        element.dataset.tooltip = text;
    },

    // Create progress bar (returns safe HTML string)
    createProgressBar(percent = 0, animated = false) {
        const animatedClass = animated ? 'progress-bar-animated' : '';
        const safePercent = Math.min(100, Math.max(0, percent));
        return `<div class="progress-bar ${animatedClass}"><div class="progress-bar-fill" style="width: ${safePercent}%;"></div></div>`;
    },

    // Update progress bar
    updateProgressBar(container, percent) {
        if (!container) return;
        const fill = container.querySelector('.progress-bar-fill');
        if (fill) {
            fill.style.width = `${Math.min(100, Math.max(0, percent))}%`;
        }
    },

    // Create status indicator (returns safe HTML string)
    createStatusDot(status = 'info', pulse = false) {
        const validStatuses = ['success', 'error', 'warning', 'info'];
        const safeStatus = validStatuses.includes(status) ? status : 'info';
        const pulseClass = pulse ? 'status-dot-pulse' : '';
        return `<span class="status-dot status-dot-${safeStatus} ${pulseClass}"></span>`;
    },

    // Create keyboard shortcut hint
    createKbd(keys) {
        if (Array.isArray(keys)) {
            return keys.map(k => {
                const kbd = document.createElement('kbd');
                kbd.className = 'kbd';
                kbd.textContent = k;
                return kbd.outerHTML;
            }).join(' + ');
        }
        const kbd = document.createElement('kbd');
        kbd.className = 'kbd';
        kbd.textContent = keys;
        return kbd.outerHTML;
    },

    // Shake element to indicate error
    shakeElement(element) {
        if (!element) return;
        element.style.animation = 'shake 0.4s ease';
        element.addEventListener('animationend', () => {
            element.style.animation = '';
        }, { once: true });
    },

    // Show inline validation message
    showValidationMessage(field, message, type = 'error') {
        const formGroup = field?.closest('.form-group');
        if (!formGroup) return;

        // Remove existing message
        const existing = formGroup.querySelector('.form-error-message, .form-success-message');
        if (existing) existing.remove();

        const className = type === 'error' ? 'form-error-message' : 'form-success-message';
        const icon = type === 'error' ? '⚠️' : '✓';

        const messageEl = document.createElement('div');
        messageEl.className = className;

        const iconSpan = document.createElement('span');
        iconSpan.textContent = icon;
        const textSpan = document.createElement('span');
        textSpan.textContent = message;

        messageEl.appendChild(iconSpan);
        messageEl.appendChild(textSpan);
        formGroup.appendChild(messageEl);

        // Auto-remove after 5 seconds
        setTimeout(() => messageEl.remove(), 5000);
    },

    // Clear validation messages from form
    clearValidationMessages(form) {
        if (!form) return;
        form.querySelectorAll('.form-error-message, .form-success-message').forEach(el => el.remove());
        form.querySelectorAll('.is-invalid, .is-valid').forEach(el => {
            el.classList.remove('is-invalid', 'is-valid');
        });
        form.querySelectorAll('.form-group').forEach(el => {
            el.classList.remove('is-invalid', 'is-valid', 'is-validating');
        });
    },

    // Set form group as validating (async validation)
    setValidating(field, isValidating = true) {
        const formGroup = field?.closest('.form-group');
        if (!formGroup) return;

        if (isValidating) {
            formGroup.classList.add('is-validating');
            formGroup.classList.remove('is-valid', 'is-invalid');
        } else {
            formGroup.classList.remove('is-validating');
        }
    }
};

// Keyboard Shortcuts Manager
const KeyboardShortcuts = {
    shortcuts: {},
    enabled: true,

    init() {
        document.addEventListener('keydown', (e) => {
            if (!this.enabled) return;

            // Don't trigger shortcuts when typing in inputs
            if (['INPUT', 'TEXTAREA', 'SELECT'].includes(e.target.tagName)) {
                return;
            }

            const key = this.getKeyCombo(e);
            const shortcut = this.shortcuts[key];

            if (shortcut) {
                e.preventDefault();
                shortcut.action();
                Toast.info(`${shortcut.name}`, { duration: 1000 });
            }
        });

        // Register default shortcuts
        this.register('ctrl+k', 'Quick Search', () => {
            const searchInput = document.querySelector('#job-search, #project-search, .jobs-search input');
            if (searchInput) {
                searchInput.focus();
                searchInput.select();
            }
        });

        this.register('ctrl+n', 'New Job', () => {
            if (Views.current !== 'submit-job') {
                Views.load('submit-job');
            }
        });

        this.register('ctrl+p', 'New Project', () => {
            App.createProject();
        });

        this.register('g+d', 'Go to Dashboard', () => Views.load('dashboard'));
        this.register('g+j', 'Go to Jobs', () => Views.load('jobs'));
        this.register('g+p', 'Go to Projects', () => Views.load('projects'));
        this.register('g+f', 'Go to Files', () => Views.load('files'));
        this.register('g+s', 'Go to Settings', () => Views.load('settings'));
    },

    getKeyCombo(e) {
        const parts = [];
        if (e.ctrlKey || e.metaKey) parts.push('ctrl');
        if (e.altKey) parts.push('alt');
        if (e.shiftKey) parts.push('shift');
        parts.push(e.key.toLowerCase());
        return parts.join('+');
    },

    register(keyCombo, name, action) {
        this.shortcuts[keyCombo] = { name, action };
    }
};

