// Copy to Clipboard Utility
const ClipboardHelper = {
    async copy(text, successMessage = 'Copied to clipboard') {
        try {
            await navigator.clipboard.writeText(text);
            Toast.success(successMessage);
            return true;
        } catch (error) {
            // Fallback for older browsers
            const textarea = document.createElement('textarea');
            textarea.value = text;
            textarea.style.position = 'fixed';
            textarea.style.opacity = '0';
            document.body.appendChild(textarea);
            textarea.select();

            try {
                document.execCommand('copy');
                Toast.success(successMessage);
                return true;
            } catch (err) {
                Toast.error('Failed to copy to clipboard');
                return false;
            } finally {
                document.body.removeChild(textarea);
            }
        }
    },

    createCopyButton(text, label = 'Copy') {
        return `
            <button class="btn btn-ghost btn-sm" onclick="ClipboardHelper.copy('${escapeJs(text)}')" title="${label}">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                    <rect x="9" y="9" width="13" height="13" rx="2" ry="2"/>
                    <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/>
                </svg>
            </button>
        `;
    }
};

// Drag and Drop File Upload
const DragDropUpload = {
    init(containerSelector, options = {}) {
        const {
            onFiles = (files) => console.log('Files:', files),
            accept = '*',
            multiple = true,
            maxSize = 100 * 1024 * 1024 // 100MB
        } = options;

        const container = document.querySelector(containerSelector);
        if (!container) return;

        // Add drag-drop styling
        container.style.position = 'relative';

        const overlay = document.createElement('div');
        overlay.className = 'drag-drop-overlay';
        overlay.style.cssText = `
            position: absolute;
            inset: 0;
            background: rgba(99, 102, 241, 0.1);
            border: 2px dashed var(--color-accent);
            border-radius: var(--radius-lg);
            display: none;
            align-items: center;
            justify-content: center;
            z-index: 1000;
            pointer-events: none;
        `;
        overlay.innerHTML = `
            <div style="text-align: center; color: var(--color-accent);">
                <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="margin: 0 auto 12px;">
                    <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>
                    <polyline points="17 8 12 3 7 8"/>
                    <line x1="12" y1="3" x2="12" y2="15"/>
                </svg>
                <div style="font-size: 18px; font-weight: 600;">Drop files here</div>
            </div>
        `;
        container.appendChild(overlay);

        let dragCounter = 0;

        container.addEventListener('dragenter', (e) => {
            e.preventDefault();
            dragCounter++;
            overlay.style.display = 'flex';
        });

        container.addEventListener('dragleave', (e) => {
            e.preventDefault();
            dragCounter--;
            if (dragCounter === 0) {
                overlay.style.display = 'none';
            }
        });

        container.addEventListener('dragover', (e) => {
            e.preventDefault();
        });

        container.addEventListener('drop', (e) => {
            e.preventDefault();
            dragCounter = 0;
            overlay.style.display = 'none';

            const files = Array.from(e.dataTransfer.files);

            // Validate files
            const validFiles = files.filter(file => {
                if (file.size > maxSize) {
                    Toast.error(`${file.name} is too large (max ${maxSize / 1024 / 1024}MB)`);
                    return false;
                }
                return true;
            });

            if (validFiles.length > 0) {
                onFiles(validFiles);
            }
        });
    }
};

// Auto-save Form Drafts
const FormAutoSave = {
    init(formSelector, storageKey, options = {}) {
        const {
            debounceMs = 1000,
            fields = [],
            onRestore = () => {},
            excludeFields = ['password', 'csrf_token']
        } = options;

        const form = document.querySelector(formSelector);
        if (!form) return;

        let saveTimeout;

        // Restore saved data
        const savedData = this.load(storageKey);
        if (savedData && Object.keys(savedData).length > 0) {
            const restore = confirm(window.i18n ? window.i18n.t('app.restoreDraft') : 'Restore previously saved draft?');
            if (restore) {
                Object.entries(savedData).forEach(([name, value]) => {
                    const field = form.querySelector(`[name="${name}"]`);
                    if (field && !excludeFields.includes(name)) {
                        field.value = value;
                    }
                });
                Toast.info('Draft restored');
                onRestore(savedData);
            } else {
                this.clear(storageKey);
            }
        }

        // Auto-save on input
        form.addEventListener('input', (e) => {
            if (excludeFields.includes(e.target.name)) return;

            clearTimeout(saveTimeout);
            saveTimeout = setTimeout(() => {
                this.save(form, storageKey, excludeFields);
            }, debounceMs);
        });

        // Clear on successful submit
        form.addEventListener('submit', () => {
            this.clear(storageKey);
        });
    },

    save(form, storageKey, excludeFields = []) {
        const data = {};
        const formData = new FormData(form);

        for (const [key, value] of formData.entries()) {
            if (!excludeFields.includes(key)) {
                data[key] = value;
            }
        }

        try {
            localStorage.setItem(storageKey, JSON.stringify(data));
        } catch (e) {
            console.warn('Failed to save form draft:', e);
        }
    },

    load(storageKey) {
        try {
            const data = localStorage.getItem(storageKey);
            return data ? JSON.parse(data) : null;
        } catch (e) {
            console.warn('Failed to load form draft:', e);
            return null;
        }
    },

    clear(storageKey) {
        try {
            localStorage.removeItem(storageKey);
        } catch (e) {
            console.warn('Failed to clear form draft:', e);
        }
    }
};

// Enhanced Toast with Actions
const ToastEnhanced = {
    show(message, options = {}) {
        const {
            type = 'info',
            duration = 3000,
            action = null, // { text: 'Undo', onClick: () => {} }
            dismissible = true
        } = options;

        const toastId = 'toast-' + Date.now();
        const toast = document.createElement('div');
        toast.id = toastId;
        toast.className = `toast toast-${type}`;
        toast.style.cssText = `
            position: fixed;
            bottom: 24px;
            right: 24px;
            min-width: 300px;
            max-width: 500px;
            background: var(--color-bg-elevated);
            border: 1px solid var(--color-border);
            border-radius: var(--radius-md);
            padding: 16px;
            box-shadow: var(--shadow-lg);
            z-index: 10000;
            display: flex;
            align-items: center;
            gap: 12px;
            animation: slideInRight 0.3s ease;
        `;

        const icon = {
            success: '✓',
            error: '✕',
            warning: '⚠',
            info: 'ℹ'
        }[type] || 'ℹ';

        toast.innerHTML = `
            <div style="flex-shrink: 0; width: 24px; height: 24px; border-radius: 50%; background: var(--color-${type === 'error' ? 'error' : type === 'success' ? 'success' : type === 'warning' ? 'warning' : 'info'}-muted); display: flex; align-items: center; justify-content: center; color: var(--color-${type === 'error' ? 'error' : type === 'success' ? 'success' : type === 'warning' ? 'warning' : 'info'});">
                ${icon}
            </div>
            <div style="flex: 1; font-size: 14px; color: var(--color-text-primary);">
                ${escapeHtml(message)}
            </div>
            ${action ? `
                <button onclick="(${action.onClick.toString()})(); document.getElementById('${toastId}').remove();" style="padding: 6px 12px; background: var(--color-accent); color: white; border: none; border-radius: var(--r-ui, 0px); font-size: 13px; font-weight: 500; cursor: pointer;">
                    ${escapeHtml(action.text)}
                </button>
            ` : ''}
            ${dismissible ? `
                <button onclick="document.getElementById('${toastId}').remove()" style="padding: 4px; background: transparent; border: none; color: var(--color-text-muted); cursor: pointer; margin-left: 4px;">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                        <line x1="18" y1="6" x2="6" y2="18"/>
                        <line x1="6" y1="6" x2="18" y2="18"/>
                    </svg>
                </button>
            ` : ''}
        `;

        document.body.appendChild(toast);

        if (duration > 0) {
            setTimeout(() => {
                toast.style.animation = 'slideOutRight 0.3s ease';
                setTimeout(() => toast.remove(), 300);
            }, duration);
        }

        return toastId;
    }
};

// Dynamic Animations Manager
const Animations = {
    // Animated Counter
    animateCounter(element, start, end, duration = 1000) {
        if (!element) return;

        const range = end - start;
        const increment = range / (duration / 16); // 60fps
        let current = start;

        element.classList.add('counting');

        const timer = setInterval(() => {
            current += increment;
            if ((increment > 0 && current >= end) || (increment < 0 && current <= end)) {
                current = end;
                clearInterval(timer);
                element.classList.remove('counting');
            }
            element.textContent = Math.floor(current).toLocaleString();
        }, 16);
    },

    // Scroll Reveal
    initScrollReveal() {
        const revealElements = document.querySelectorAll('.scroll-reveal, .scroll-reveal-left, .scroll-reveal-right');

        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('revealed');
                    observer.unobserve(entry.target);
                }
            });
        }, {
            threshold: 0.1,
            rootMargin: '0px 0px -50px 0px'
        });

        revealElements.forEach(el => observer.observe(el));
    },

    // Page Transition
    transitionPage(callback) {
        const contentArea = document.getElementById('content-area');
        if (!contentArea) {
            callback();
            return;
        }

        // Exit animation
        contentArea.classList.add('view-transition-exit');

        setTimeout(() => {
            callback();

            // Enter animation
            contentArea.classList.remove('view-transition-exit');
            contentArea.classList.add('view-transition-enter');

            setTimeout(() => {
                contentArea.classList.remove('view-transition-enter');
                this.initScrollReveal(); // Re-init for new content
            }, 400);
        }, 200);
    },

    // Stagger Animation
    staggerElements(selector, delay = 50) {
        const elements = document.querySelectorAll(selector);
        elements.forEach((el, index) => {
            el.classList.add('stagger-item');
            el.style.animationDelay = `${index * delay}ms`;
        });
    },

    // Ripple Effect
    createRipple(event, element) {
        const ripple = document.createElement('span');
        const rect = element.getBoundingClientRect();

        const size = Math.max(rect.width, rect.height);
        const x = event.clientX - rect.left - size / 2;
        const y = event.clientY - rect.top - size / 2;

        ripple.style.cssText = `
            position: absolute;
            width: ${size}px;
            height: ${size}px;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.5);
            top: ${y}px;
            left: ${x}px;
            pointer-events: none;
            animation: rippleEffect 0.6s ease-out;
        `;

        // Add ripple animation
        const style = document.createElement('style');
        style.textContent = `
            @keyframes rippleEffect {
                to {
                    transform: scale(4);
                    opacity: 0;
                }
            }
        `;
        if (!document.querySelector('#ripple-style')) {
            style.id = 'ripple-style';
            document.head.appendChild(style);
        }

        element.style.position = 'relative';
        element.style.overflow = 'hidden';
        element.appendChild(ripple);

        setTimeout(() => ripple.remove(), 600);
    },

    // Progress Bar Animation
    animateProgress(element, targetPercent, duration = 1000) {
        if (!element) return;

        let currentPercent = 0;
        const increment = targetPercent / (duration / 16);

        const timer = setInterval(() => {
            currentPercent += increment;
            if (currentPercent >= targetPercent) {
                currentPercent = targetPercent;
                clearInterval(timer);
            }
            element.style.width = `${currentPercent}%`;
        }, 16);
    }
};

