    // Submit Job View
    async renderSubmitJob() {
        const response = await API.get('/api/projects');
        // Ensure projects is always an array - handle API errors gracefully
        const projects = Array.isArray(response) ? response : [];
        if (!Array.isArray(response)) {
            console.error('API /api/projects returned non-array:', response);
        }
        const selectedProjectId = sessionStorage.getItem('selectedProject') || (projects.length > 0 ? projects[0].id : null);

        this.contentArea.innerHTML = `
            ${this.createHeroBanner({
                gradient: 'linear-gradient(135deg, #ec4899 0%, #db2777 100%)',
                icon: `<svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2">
                    <polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/>
                </svg>`,
                title: 'Submit Job',
                description: 'Run computational analyses including protein folding, molecular docking, and structure prediction with cutting-edge AI models.',
                buttons: []
            })}

            <div class="card" style="margin-bottom: var(--space-4); border-left: 3px solid var(--accent-warning); background: var(--accent-warning-muted);">
                <div class="card-body" style="display: flex; gap: 12px; align-items: flex-start; padding: var(--space-4);">
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="var(--accent-warning)" stroke-width="2" style="flex-shrink: 0; margin-top: 1px;">
                        <circle cx="12" cy="12" r="10"/>
                        <line x1="12" y1="16" x2="12" y2="12"/>
                        <line x1="12" y1="8" x2="12.01" y2="8"/>
                    </svg>
                    <div style="font-size: 13px; line-height: 1.5;">
                        <strong style="color: var(--text-primary);" data-i18n="submitJob.researchPreviewNote.title">Research Preview</strong>
                        <span style="color: var(--text-secondary);" data-registry-note="preview"> &mdash; ${escapeHtml(ModelRegistry.previewNote())}</span>
                    </div>
                </div>
            </div>

            <div class="card">
                <div class="card-header">
                    <h3 class="card-title">Submit Job</h3>
                </div>
                <div class="card-body" style="padding: 0;">
                    <div class="form-group" style="padding: var(--space-4); margin-bottom: 0; border-bottom: 1px solid var(--color-border);">
                        <label class="form-label">Select Project</label>
                        <select class="form-select" id="wizard-project-select" onchange="App.submitJobForProject(this.value, document.getElementById('wizard-container'))" style="max-width: 400px;">
                            <option value="">Select a project...</option>
                            ${projects.map(p => `<option value="${p.id}" ${p.id == selectedProjectId ? 'selected' : ''}>${escapeHtml(p.name)}</option>`).join('')}
                        </select>
                    </div>
                    <div id="wizard-container" style="padding: var(--space-4);">
                        <!-- Wizard will be rendered here -->
                    </div>
                </div>
            </div>
        `;

        // Trigger wizard load if project is selected
        if (selectedProjectId) {
            setTimeout(() => {
                App.submitJobForProject(selectedProjectId, document.getElementById('wizard-container'));
            }, 100);
        } else if (projects.length === 0) {
            document.getElementById('wizard-container').innerHTML = `
                <div class="empty-state">
                    <p class="text-muted">You need to create a project before submitting a job.</p>
                    <button class="btn btn-primary" onclick="App.createProject()">Create Project</button>
                </div>
            `;
        }
    },

