    _renderWebhookCard(webhook, index) {
        const isActive = webhook.is_active;
        const total = (webhook.stats.success_count || 0) + (webhook.stats.failure_count || 0);
        const successRate = total > 0
            ? Math.round((webhook.stats.success_count / total) * 100)
            : 100;
        const rateColor = successRate >= 90 ? '#34d399' : successRate >= 70 ? '#fbbf24' : '#f87171';

        // All user data escaped
        const eventBadges = (webhook.events || []).map(function(e) {
            return '<span class="badge badge-info">' + escapeHtml(e) + '</span>';
        }).join('');

        return [
            '<article class="resource-card-v2 ' + (!isActive ? 'is-inactive' : '') + '" style="--card-accent: #06b6d4;">',
            '  <div class="resource-card-v2-top">',
            '    <div class="resource-card-v2-heading">',
            '      <div class="resource-card-v2-badges" style="margin-top:0;">',
            '        <span class="badge ' + (isActive ? 'badge-success' : '') + '"' + (!isActive ? ' style="background:rgba(255,255,255,0.06);color:var(--text-muted);"' : '') + '>' + (isActive ? 'Active' : 'Disabled') + '</span>',
            '        ' + eventBadges,
            '      </div>',
            '      <div class="resource-card-v2-secret" style="margin-top:6px;">',
            '        <code>' + escapeHtml(webhook.url) + '</code>',
            '      </div>',
            webhook.description ? '      <p class="resource-card-v2-description">' + escapeHtml(webhook.description) + '</p>' : '',
            '    </div>',
            '    <div class="resource-card-v2-actions">',
            '      <button class="btn btn-sm btn-secondary" onclick="Views.testWebhook(' + webhook.id + ')">Test</button>',
            '      <button class="btn btn-sm btn-secondary" onclick="Views.editWebhook(' + webhook.id + ')">Edit</button>',
            '      <button class="btn btn-sm btn-ghost" onclick="Views.deleteWebhook(' + webhook.id + ')" title="Delete" style="color:var(--accent-danger-light,#f87171);"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button>',
            '    </div>',
            '  </div>',
            '  <div class="resource-card-v2-rate">',
            '    <div class="resource-card-v2-rate-bar"><div class="resource-card-v2-rate-fill" style="width:' + successRate + '%;background:' + rateColor + ';"></div></div>',
            '    <span class="resource-card-v2-rate-label" style="color:' + rateColor + ';">' + successRate + '%</span>',
            '  </div>',
            '  <div class="resource-card-v2-stats">',
            '    <div class="resource-card-v2-stat"><div class="resource-card-v2-stat-value">' + (webhook.stats.success_count || 0) + '</div><div class="resource-card-v2-stat-label">Success</div></div>',
            '    <div class="resource-card-v2-stat"><div class="resource-card-v2-stat-value">' + (webhook.stats.failure_count || 0) + '</div><div class="resource-card-v2-stat-label">Failed</div></div>',
            '    <div class="resource-card-v2-stat"><div class="resource-card-v2-stat-value">' + (webhook.last_triggered_at ? new Date(webhook.last_triggered_at).toLocaleDateString() : 'Never') + '</div><div class="resource-card-v2-stat-label">Last Triggered</div></div>',
            '  </div>',
            '</article>'
        ].join('\n');
    },

