    updateAPITesterBody() {
        const endpoint = document.getElementById('api-test-endpoint')?.value || '';
        const body = document.getElementById('api-test-body');
        if (!body) return;

        if (endpoint.includes('POST /v1/predict')) {
            body.value = JSON.stringify({
                model: "esmfold",
                sequence: "MGSSHHHHHHSSGLVPRGSH",
                name: "Test Protein"
            }, null, 2);
        } else {
            body.value = '';
        }
    },

    async executeAPITest() {
        const endpoint = document.getElementById('api-test-endpoint')?.value || '';
        const bodyText = document.getElementById('api-test-body')?.value || '';
        const apiKey = document.getElementById('api-test-key')?.value || '';
        const responseEl = document.getElementById('api-test-response');

        if (!responseEl) return;

        if (!apiKey) {
            responseEl.innerHTML = '<span class="dev-api-response__error">Please enter your API key</span>';
            return;
        }

        const [method, path] = endpoint.split(' ');

        responseEl.innerHTML = '<span class="dev-api-response__pending">Sending request...</span>';

        try {
            const options = { method };
            if (method === 'POST' && bodyText) {
                options.body = bodyText;
            }

            const startTime = performance.now();
            const response = await fetch(path, {
                ...options,
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${apiKey}`
                }
            });
            const endTime = performance.now();

            const data = await response.json();
            responseEl.innerHTML = `<div class="dev-api-response__meta">
                <span class="dev-api-response__status ${response.ok ? 'is-ok' : 'is-error'}">Status: ${response.status}</span>
                <span class="dev-api-response__time">Time: ${Math.round(endTime - startTime)}ms</span>
            </div>
            <pre>${JSON.stringify(data, null, 2)}</pre>`;
        } catch (error) {
            responseEl.innerHTML = `<span class="dev-api-response__error">Error: ${error.message}</span>`;
        }
    },

