    copyAPIKey() {
        const input = document.getElementById('api-key-value');
        const text = input.value;
        navigator.clipboard.writeText(text).then(() => {
            Toast.success('API key copied to clipboard');
        }).catch(() => {
            // Fallback for older browsers
            const textArea = document.createElement('textarea');
            textArea.value = text;
            textArea.style.position = 'fixed';
            textArea.style.opacity = '0';
            document.body.appendChild(textArea);
            textArea.select();
            document.execCommand('copy');
            document.body.removeChild(textArea);
            Toast.success('API key copied to clipboard');
        });
    },

    async toggleAPIKey(keyId, currentStatus) {
        try {
            const response = await API.post(`/api/keys/${keyId}/toggle`, { is_active: !currentStatus });
            if (response.status === 'success') {
                Toast.success(response.message);
                await this.renderAPITokens();
            }
        } catch (error) {
            Toast.error(error.message || 'Failed to toggle API key');
        }
    },

    async deleteAPIKey(keyId) {
        if (!confirm(window.i18n ? window.i18n.t('app.deleteApiKey') : 'Are you sure you want to delete this API key? This action cannot be undone.')) {
            return;
        }

        try {
            const response = await API.delete(`/api/keys/${keyId}`);
            if (response.status === 'success') {
                Toast.success('API key deleted');
                await this.renderAPITokens();
            }
        } catch (error) {
            Toast.error(error.message || 'Failed to delete API key');
        }
    },

    // Usage Analytics View
