    async sendBulkStudentInvitations(projectId) {
        const textarea = document.getElementById(`invite-emails-${projectId}`);
        const raw = textarea?.value?.trim();
        if (!raw) {
            Toast.error('Enter at least one student email address');
            return;
        }

        try {
            const resp = await API.post(`/api/projects/${projectId}/invitations/bulk`, { emails: raw });
            const invited = resp.invited || 0;
            const total = resp.total || 0;
            const results = resp.results || [];

            if (invited === total) {
                Toast.success(`Invited ${invited} student${invited === 1 ? '' : 's'}.`);
            } else {
                // Surface the addresses that didn't go through so the teacher can fix them.
                const skipped = results.filter(r => r.status !== 'invited');
                const detail = skipped.slice(0, 5).map(r => `${r.email}: ${r.message}`).join('\n');
                const more = skipped.length > 5 ? `\n…and ${skipped.length - 5} more.` : '';
                if (invited > 0) {
                    Toast.warning(`Invited ${invited} of ${total}. Skipped:\n${detail}${more}`);
                } else {
                    Toast.error(`No invitations sent.\n${detail}${more}`);
                }
            }

            if (invited > 0) {
                textarea.value = '';
                Views.load('project');
            }
        } catch (error) {
            Toast.error(error.message || 'Failed to send invitations');
        }
    },

