    async saveProjectSettings(projectId) {
        const name = document.getElementById('project-name-input').value.trim();
        const description = document.getElementById('project-desc-input').value.trim();
        // All projects are private for now; public projects are disabled.
        const isPrivate = true;
        const billingModeSelect = document.getElementById('project-billing-mode');
        const billingMode = billingModeSelect ? billingModeSelect.value : null;

        if (!name) {
            Toast.error('Project name is required');
            return;
        }

        try {
            const payload = {
                name: name,
                description: description,
                is_private: isPrivate
            };

            // Only include billing mode if the selector exists (manager only)
            if (billingMode) {
                payload.collaboration_billing_model = billingMode;
            }

            await API.patch(`/api/projects/${projectId}`, payload);
            Toast.success('Project settings saved');
            Views.load('project');
        } catch (error) {
            Toast.error(error.message || 'Failed to save project settings');
        }
    },

