    async bulkDeleteProjectFiles(projectId) {
        const checked = Array.from(document.querySelectorAll('#project-files-table-body .project-file-cb:checked'))
            .filter(cb => cb.dataset.isOutput !== '1');
        if (checked.length === 0) {
            Toast.warning('No uploaded files selected. Job output files must be deleted individually.');
            return;
        }
        const fileIds = checked.map(cb => Number(cb.value));
        const skipped = Array.from(document.querySelectorAll('#project-files-table-body .project-file-cb:checked')).length - checked.length;
        const skipNote = skipped > 0 ? ' (' + skipped + ' job output' + (skipped === 1 ? '' : 's') + ' skipped)' : '';
        Modal.open({
            title: 'Delete ' + fileIds.length + ' File' + (fileIds.length === 1 ? '' : 's'),
            content: '<p>Permanently delete <strong>' + fileIds.length + ' file' + (fileIds.length === 1 ? '' : 's') + '</strong>' + skipNote + '? This cannot be undone.</p>',
            confirmText: 'Delete All',
            onConfirm: async () => {
                try {
                    const result = await API.post('/api/projects/' + projectId + '/files/bulk-delete', { file_ids: fileIds });
                    Toast.success('Deleted ' + (result.deleted_count || fileIds.length) + ' file(s)');
                    App.selectProject(projectId);
                } catch (err) {
                    Toast.error(err.message || 'Failed to delete files');
                }
            }
        });
    },

    async useProjectFilesAsInput(projectId) {
        const checked = Array.from(document.querySelectorAll('#project-files-table-body .project-file-cb:checked'))
            .filter(cb => cb.dataset.isOutput !== '1');
        if (checked.length === 0) {
            Toast.warning('Select uploaded input files to use as job input.');
            return;
        }
        const fileIds = checked.map(cb => Number(cb.value));

        // Store file IDs — content is fetched after model selection when the form is ready
        window._pendingInputFileIds = { projectId: Number(projectId), fileIds: fileIds };

        const existingForm = document.getElementById('inline-job-form-' + projectId);
        if (!existingForm) {
            await App.submitJobForProject(projectId);
        }

        setTimeout(function() {
            var form = document.getElementById('inline-job-form-' + projectId);
            if (!form) return;
            form.scrollIntoView({ behavior: 'smooth', block: 'start' });
            // If a model is already selected and the batch container is ready, load immediately
            var batchContainer = document.getElementById('batch-sequences-container-' + projectId);
            if (batchContainer) {
                App._loadPendingFilesIntoForm(projectId);
            } else {
                var n = fileIds.length;
                Toast.info(n + ' file' + (n !== 1 ? 's' : '') + ' selected \u2014 choose a model to load them');
            }
        }, 400);
    },

    async _loadPendingFilesIntoForm(projectId) {
        var pending = window._pendingInputFileIds;
        if (!pending || Number(pending.projectId) !== Number(projectId)) return;

        var batchContainer = document.getElementById('batch-sequences-container-' + projectId);
        if (!batchContainer) return;

        delete window._pendingInputFileIds;
        var fileIds = pending.fileIds;

        var loadingToast = Toast.info('Loading ' + fileIds.length + ' file' + (fileIds.length !== 1 ? 's' : '') + '\u2026');

        // Fetch all file contents — bulk endpoint preferred, chunked fallback if unavailable
        var fileContentMap = {};
        var bulkOk = false;
        try {
            var bulkResponse = await API.post('/api/files/bulk-content', { file_ids: fileIds });
            if (bulkResponse && bulkResponse.files) {
                bulkResponse.files.forEach(function(f) {
                    if (f.content) fileContentMap[f.id] = f;
                });
                bulkOk = true;
            }
        } catch (e) {
            console.warn('Bulk file fetch failed, falling back to individual requests:', e);
        }
        if (!bulkOk) {
            for (var ci = 0; ci < fileIds.length; ci += 5) {
                var chunk = fileIds.slice(ci, ci + 5);
                var chunkRes = await Promise.allSettled(chunk.map(function(fid) { return fetchFileContent(fid); }));
                chunkRes.forEach(function(r, i) {
                    if (r.status === 'fulfilled' && r.value && r.value.content) {
                        fileContentMap[chunk[i]] = r.value;
                    }
                });
            }
        }
        var results = fileIds.map(function(fid) {
            var f = fileContentMap[fid];
            return f ? { status: 'fulfilled', value: f } : { status: 'rejected' };
        });

        var totalLoaded = 0;
        var errors = 0;
        results.forEach(function(result) {
            if (result.status !== 'fulfilled' || !result.value || !result.value.content) { errors++; return; }

            var sequences = App.parseMultiFASTA(result.value.content);
            if (sequences.length === 0) {
                var plain = result.value.content.trim().replace(/[^A-Za-z*\-\n]/g, '').replace(/\n/g, '').toUpperCase();
                if (plain.length > 0) sequences = [{ name: 'Sequence', sequence: plain }];
            }
            if (sequences.length === 0) { errors++; return; }

            sequences.forEach(function(seq) {
                var existingItems = batchContainer.querySelectorAll('.batch-sequence-item');
                var firstTextarea = existingItems[0] ? existingItems[0].querySelector('.batch-sequence-input') : null;
                var firstIsEmpty = firstTextarea && !firstTextarea.value.trim();
                var targetItem;
                if (totalLoaded === 0 && firstIsEmpty) {
                    targetItem = existingItems[0];
                } else {
                    App.addBatchSequence(projectId);
                    var items = batchContainer.querySelectorAll('.batch-sequence-item');
                    targetItem = items[items.length - 1];
                }
                if (targetItem) {
                    var textarea = targetItem.querySelector('.batch-sequence-input');
                    var nameInput = targetItem.querySelector('.batch-sequence-name');
                    if (textarea) {
                        textarea.value = seq.sequence;
                        App.validateBatchSequenceInput(textarea, projectId, parseInt(targetItem.dataset.index, 10));
                    }
                    if (nameInput && seq.name && seq.name !== 'Sequence') nameInput.value = seq.name;
                    totalLoaded++;
                }
            });
        });

        var msg = totalLoaded + ' sequence' + (totalLoaded !== 1 ? 's' : '') + ' loaded from ' + fileIds.length + ' file' + (fileIds.length !== 1 ? 's' : '');
        if (errors > 0) Toast.warning(msg + ' (' + errors + ' file' + (errors !== 1 ? 's' : '') + ' could not be parsed)');
        else if (totalLoaded > 0) Toast.success(msg);
        else Toast.warning('No sequence data found in selected files. Files must be FASTA or plain text format.');
    },

