    async loadPDBFile() {
        const jobId = document.getElementById('viewer-file').value;
        if (!jobId) {
            Toast.warning('Please select a file');
            return;
        }

        const viewerElement = document.getElementById('viewer-container');
        if (!viewerElement) return;

        // Reset viewer container if it contains empty state
        if (viewerElement.querySelector('.empty-state')) {
            viewerElement.replaceChildren();
            viewerElement.style.position = 'relative';
            this.viewer3d = null; // Force re-init
        }

        // Initialize viewer if needed
        if (!this.viewer3d) {
            if (typeof PhonosViewer === 'undefined') {
                Toast.error('PhonosViewer library not loaded');
                return;
            }

            if (!viewerElement.id) viewerElement.id = 'viewer-container';
            viewerElement.setAttribute('data-phonos-viewer', 'true');
            this.viewer3d = PhonosViewer.create(viewerElement.id, { hideControls: false, sequencePanel: true, focusPanel: false });
            window._phonosViewer = this.viewer3d;
        }

        Toast.info('Loading molecular structure...');

        try {
            // Fetch the file
            const response = await fetch('/download_output/' + jobId);
            if (!response.ok) throw new Error('Failed to download structure file');

            const data = await response.text();

            // Detect format
            let format = 'pdb';
            if (data.includes('data_') || data.includes('_atom_site')) format = 'cif';
            else if (data.includes('RDKit') || data.includes('M  END')) format = 'sdf';
            else if (data.trim().startsWith('{')) {
                // Handle JSON output (e.g. Evo2 or unexpected)
                throw new Error('Selected file is JSON, not a 3D structure');
            }

            this.viewer3d.loadData(data, format);

            Toast.success('Structure loaded successfully');

        } catch (error) {
            console.error(error);
            Toast.error('Error loading structure: ' + error.message);
            // Optionally restore empty state
            if (!this.viewer3d) {
                var errDiv = document.createElement('div');
                errDiv.className = 'empty-state';
                var errTitle = document.createElement('h3');
                errTitle.className = 'empty-state-title';
                errTitle.textContent = 'Error Loading Structure';
                errDiv.appendChild(errTitle);
                var errDesc = document.createElement('p');
                errDesc.className = 'empty-state-description';
                errDesc.textContent = error.message;
                errDiv.appendChild(errDesc);
                viewerElement.replaceChildren(errDiv);
            }
        }
    },

