    async setLanguage(lang) {
        if (!window.i18n || typeof window.i18n.setLanguage !== 'function') {
            Toast.error('Language system is not available');
            return;
        }
        // setLanguage persists the choice (localStorage + cookie), repaints all
        // [data-i18n] elements, and notifies listeners.
        await window.i18n.setLanguage(lang);
        // setLanguage already repaints every [data-i18n] element live, so no
        // view re-render is needed — the UI updates in place.
        const name = window.i18n.t(lang === 'de' ? 'language.german' : 'language.english');
        Toast.success(window.i18n.t('language.changed', { language: name }));
    },

