App.addSchemaField = function(data = null) {
    const container = document.getElementById('schema-fields-list');
    if (!container) return;

    const div = document.createElement('div');
    div.className = 'schema-field-item';
    div.style.cssText = 'padding: 12px; background: rgba(0,0,0,0.15); border: 1px solid var(--color-border); border-radius: var(--r-ui, 0px); margin-bottom: 8px; transition: border-color 0.15s;';

    const nameVal = data?.name || '';
    const labelVal = data?.label || '';
    const defaultVal = data?.default || '';
    const isReq = data?.required !== false;
    const selText = data?.type === 'text' ? ' selected' : '';
    const selNum = data?.type === 'number' ? ' selected' : '';
    const selBool = data?.type === 'boolean' ? ' selected' : '';
    const selFile = data?.type === 'file' ? ' selected' : '';
    const selSel = data?.type === 'select' ? ' selected' : '';

    // Build safe DOM content using textContent for user values, attr for safe values
    const header = document.createElement('div');
    header.style.cssText = 'display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;';
    const headerLabel = document.createElement('span');
    headerLabel.style.cssText = 'font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.4px;color:var(--color-text-secondary);';
    headerLabel.textContent = 'Parameter';
    const removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.style.cssText = 'font-size:11px;font-weight:600;color:var(--color-error,#ef4444);background:none;border:none;cursor:pointer;padding:2px 6px;border-radius: var(--r-ui, 0px);';
    removeBtn.textContent = 'Remove';
    removeBtn.onclick = function() { div.remove(); App.updateModelPreview(); App._updateSchemaFieldCount(); };
    header.appendChild(headerLabel);
    header.appendChild(removeBtn);

    const rowTop = document.createElement('div');
    rowTop.style.cssText = 'display:grid;grid-template-columns:2fr 1.5fr auto;gap:8px;margin-bottom:8px;';

    const nameWrap = document.createElement('div');
    const nameInput = document.createElement('input');
    nameInput.type = 'text';
    nameInput.className = 'form-input field-name';
    nameInput.placeholder = 'key_name';
    nameInput.value = nameVal;
    nameInput.required = true;
    nameInput.style.cssText = 'font-family:monospace;font-size:12px;';
    nameInput.oninput = () => { App.updateModelPreview(); };
    const nameHint = document.createElement('div');
    nameHint.style.cssText = 'font-size:10px;color:var(--color-text-secondary);margin-top:3px;';
    nameHint.textContent = 'JSON key';
    nameWrap.appendChild(nameInput);
    nameWrap.appendChild(nameHint);

    const typeWrap = document.createElement('div');
    const typeSelect = document.createElement('select');
    typeSelect.className = 'form-select field-type';
    typeSelect.style.cssText = 'font-size:12px;';
    typeSelect.innerHTML = '<option value="text"' + selText + '>Text</option><option value="number"' + selNum + '>Number</option><option value="boolean"' + selBool + '>Boolean</option><option value="file"' + selFile + '>File</option><option value="select"' + selSel + '>Select</option>';
    typeSelect.onchange = () => App.updateModelPreview();
    const typeHint = document.createElement('div');
    typeHint.style.cssText = 'font-size:10px;color:var(--color-text-secondary);margin-top:3px;';
    typeHint.textContent = 'Type';
    typeWrap.appendChild(typeSelect);
    typeWrap.appendChild(typeHint);

    const reqWrap = document.createElement('div');
    reqWrap.style.cssText = 'display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;';
    const reqLabel = document.createElement('label');
    reqLabel.style.cssText = 'display:flex;flex-direction:column;align-items:center;gap:3px;cursor:pointer;font-size:10px;font-weight:600;color:var(--color-text-secondary);';
    const reqCheck = document.createElement('input');
    reqCheck.type = 'checkbox';
    reqCheck.className = 'field-required';
    reqCheck.checked = isReq;
    reqCheck.onchange = () => App.updateModelPreview();
    reqLabel.appendChild(reqCheck);
    reqLabel.appendChild(document.createTextNode('Req.'));
    reqWrap.appendChild(reqLabel);

    rowTop.appendChild(nameWrap);
    rowTop.appendChild(typeWrap);
    rowTop.appendChild(reqWrap);

    const rowBottom = document.createElement('div');
    rowBottom.style.cssText = 'display:grid;grid-template-columns:1fr 1fr;gap:8px;padding-top:8px;border-top:1px dashed var(--color-border);';

    const labelInput = document.createElement('input');
    labelInput.type = 'text';
    labelInput.className = 'form-input field-label';
    labelInput.placeholder = 'UI Label (e.g. Protein Sequence)';
    labelInput.value = labelVal;
    labelInput.style.cssText = 'font-size:12px;';
    labelInput.oninput = () => App.updateModelPreview();

    const defInput = document.createElement('input');
    defInput.type = 'text';
    defInput.className = 'form-input field-default';
    defInput.placeholder = 'Default value (optional)';
    defInput.value = defaultVal;
    defInput.style.cssText = 'font-size:12px;';
    defInput.oninput = () => App.updateModelPreview();

    rowBottom.appendChild(labelInput);
    rowBottom.appendChild(defInput);

    div.appendChild(header);
    div.appendChild(rowTop);
    div.appendChild(rowBottom);
    container.appendChild(div);

    App._updateSchemaFieldCount();
};

App.collectSchemaFields = function() {
    const fields = [];
    document.querySelectorAll('.schema-field-item').forEach(item => {
        const nameInput = item.querySelector('.field-name');
        if (!nameInput) return;
        
        const name = nameInput.value.trim();
        if (name) {
            fields.push({
                name: name,
                type: item.querySelector('.field-type').value,
                label: item.querySelector('.field-label').value.trim() || name,
                default: item.querySelector('.field-default').value,
                required: item.querySelector('.field-required').checked
            });
        }
    });
    return fields;
};

App.updateModelPreview = function(modelId = 'NEW_MODEL_ID') {
    const schema = App.collectSchemaFields();
    const modelName = document.getElementById('model-name-input')?.value.trim() || 'My Custom Model';

    // Update Model ID display
    const modelIdEl = document.getElementById('preview-model-id');
    if (modelIdEl) {
        modelIdEl.textContent = modelId === 'NEW_MODEL_ID' || modelId === 'NEW' ? 'NEW (assigned on save)' : modelId;
    }

    // 1. Generate JSON Payload
    const payload = {};
    schema.forEach(field => {
        let exampleVal;
        if (field.default) {
            exampleVal = field.type === 'number' ? Number(field.default) : field.type === 'boolean' ? (field.default === 'true') : field.default;
        } else {
            switch(field.type) {
                case 'text': exampleVal = "example_text"; break;
                case 'number': exampleVal = 42; break;
                case 'boolean': exampleVal = true; break;
                case 'file': exampleVal = "file_uuid_from_upload"; break;
                case 'select': exampleVal = "option_1"; break;
                default: exampleVal = null;
            }
        }
        payload[field.name] = exampleVal;
    });

    const fullPayload = {
        "model_id": modelId,
        "job_name": "Test Run: " + modelName,
        "input": payload
    };
    
    const jsonEl = document.getElementById('preview-json');
    if (jsonEl) {
        // Simple syntax highlighting for JSON
        const jsonStr = JSON.stringify(fullPayload, null, 2);
        jsonEl.textContent = jsonStr;
    }

    // 2. Generate Python Worker Code (Site → Custom Node → Site)
    const codeEl = document.getElementById('preview-code');
    if (codeEl) {
        const pythonCode = `"""
Custom Model Worker: ${modelName}
Hardened flow with signed requests + encrypted payloads.
"""
import json
import time
import hmac
import hashlib
import requests
from user_model_crypto import encrypt_data, decrypt_data

API_KEY = "your_worker_api_key_here"  # Shown once on key creation
BASE_URL = "${window.location.origin}/api/bridge/v1"

def sign_payload(payload_dict):
    body = json.dumps(payload_dict, separators=(",", ":"))
    ts = int(time.time())
    sig = hmac.new(API_KEY.encode("utf-8"), f"{ts}.{body}".encode("utf-8"), hashlib.sha256).hexdigest()
    return body, {
        "Authorization": f"Bearer {API_KEY}",
        "Content-Type": "application/json",
        "X-Timestamp": str(ts),
        "X-Signature": sig,
    }

def process_job(input_data):
    # Your custom model logic
    return {"status": "completed", "output": "Processed data", "confidence": 0.95}

while True:
    try:
        poll_payload = {"max_jobs": 1}
        poll_body, poll_headers = sign_payload(poll_payload)
        response = requests.post(f"{BASE_URL}/jobs/poll", headers=poll_headers, data=poll_body, timeout=30)
        jobs = response.json().get("jobs", [])

        for wrapped_job in jobs:
            job = decrypt_data(wrapped_job["data"], API_KEY) if wrapped_job.get("encrypted") else wrapped_job
            job_id = job["job_id"]
            result = process_job(job["input_data"])

            result_payload = {"status": "completed", "result": result}
            encrypted_result = encrypt_data(result_payload, API_KEY)
            submit_payload = {"encrypted": True, "data": encrypted_result}
            submit_body, submit_headers = sign_payload(submit_payload)

            requests.post(
                f"{BASE_URL}/jobs/{job_id}/result",
                headers=submit_headers,
                data=submit_body,
                timeout=30,
            )

        time.sleep(5)
    except KeyboardInterrupt:
        break
    except Exception as e:
        print(f"Worker error: {e}")
        time.sleep(10)`;

        codeEl.textContent = pythonCode;
    }
};

App.saveUserModel = async function() {
    const form = document.getElementById('model-builder-form');
    if (!form) return;

    const formData = new FormData(form);
    const modelId = formData.get('model_id');
    const isEdit = !!modelId;
    const schema = App.collectSchemaFields();

    if (schema.length === 0) {
        Toast.error('Please add at least one input parameter');
        return;
    }

    // Validate required fields
    const modelName = formData.get('model_name');
    const modelDesc = formData.get('model_description');
    const projectId = formData.get('project_id');

    if (!modelName || !modelDesc) {
        Toast.error('Please fill in all required fields');
        return;
    }

    if (!projectId) {
        Toast.error('Please select a project');
        return;
    }

    const payload = {
        model_name: modelName,
        model_description: modelDesc,
        project_id: parseInt(projectId),
        credit_cost: parseInt(formData.get('credit_cost')),
        estimated_runtime_seconds: parseInt(formData.get('estimated_runtime_seconds')),
        input_schema: schema
    };

    const submitBtn = form.querySelector('button[onclick="App.saveUserModel()"]');
    UIEnhancements.setButtonLoading(submitBtn, true);

    try {
        if (isEdit) {
            await API.put(`/api/user-models/${modelId}`, payload);
            Toast.success('Model updated successfully');
        } else {
            await API.post('/api/user-models', payload);
            Toast.success('Model created successfully');
        }
        Views.load('user-models');
    } catch (error) {
        Toast.error(error.message || 'Failed to save model');
    } finally {
        UIEnhancements.setButtonLoading(submitBtn, false);
    }
};

App.createUserModel = function() {
    Views.load('user-models', { create: true });
};

App.editUserModel = function(modelId) {
    Views.load('user-models', { modelId: modelId });
};

// Builder section accordion toggle
App._toggleBuilderSection = function(sectionId) {
    const el = document.getElementById(sectionId);
    if (el) el.classList.toggle('collapsed');
};

// Builder preview tab switcher (Integration / Format Guide)
App._switchBuilderPreviewTab = function(tab) {
    ['preview', 'examples'].forEach(t => {
        const btn = document.getElementById('mb-tab-' + t);
        const panel = document.getElementById('mb-panel-' + t);
        if (btn) {
            btn.classList.toggle('active', t === tab);
            btn.setAttribute('aria-selected', t === tab ? 'true' : 'false');
        }
        if (panel) {
            panel.style.display = t === tab ? '' : 'none';
            panel.classList.toggle('active', t === tab);
        }
    });
    // Sync mb-format-chip active state when switching to examples
    if (tab === 'examples') {
        const activeFmt = document.querySelector('.mb-format-chip.active');
        if (!activeFmt) {
            const firstFmt = document.querySelector('.mb-format-chip');
            if (firstFmt) firstFmt.classList.add('active');
        }
    }
};

// Copy a snippet block (preview-json / preview-code) and flip the button label.
App._copySnippet = function(btn) {
    const targetId = btn.getAttribute('data-snippet-target');
    const el = targetId ? document.getElementById(targetId) : null;
    if (!el) return;
    const text = el.textContent || '';
    App.copyText(text).then(() => {
        const orig = btn.textContent;
        btn.textContent = 'Copied';
        btn.classList.add('copied');
        setTimeout(() => {
            btn.textContent = orig;
            btn.classList.remove('copied');
        }, 1500);
    });
};

// Copy arbitrary text and give a transient "Copied!" label on the trigger button.
App._copyTextWithFeedback = function(btn, text) {
    if (!btn) return App.copyText(text);
    App.copyText(String(text || '')).then(() => {
        const orig = btn.textContent;
        btn.textContent = 'Copied';
        btn.classList.add('copied');
        setTimeout(() => {
            btn.textContent = orig;
            btn.classList.remove('copied');
        }, 1500);
    });
};

// Tab switcher for the post-creation worker-key modal.
App._switchApiKeyTab = function(tab) {
    document.querySelectorAll('.apkm-tab').forEach(t => {
        const on = t.getAttribute('data-apkm-tab') === tab;
        t.classList.toggle('active', on);
        t.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    document.querySelectorAll('.apkm-section').forEach(s => {
        s.classList.toggle('active', s.getAttribute('data-apkm-section') === tab);
        s.style.display = s.getAttribute('data-apkm-section') === tab ? 'block' : 'none';
    });
};

// Copy the freshly minted worker key from the key tab and flash the button.
App._copyNewKey = function(btn) {
    const targetId = btn.getAttribute('data-key-target');
    const el = targetId ? document.getElementById(targetId) : null;
    const text = el ? (el.value || el.textContent) : (window._newWorkerApiKey || '');
    if (!text) {
        Toast.error('No key to copy');
        return;
    }
    const orig = btn.textContent;
    btn.textContent = 'Copying…';
    btn.disabled = true;
    App.copyText(text).then(() => {
        btn.textContent = 'Copied ✓';
        btn.classList.add('copied');
        // Long, sticky toast so the user has time to react.
        Toast.success('Worker key copied to clipboard — save it before closing this dialog', 10000);
        // Flip the hero status to a green "saved" indicator so the user
        // has a persistent visual confirmation that the key was copied.
        App._markKeyModalAsSaved();
        // Re-enable the button after a noticeably long pause so the
        // user can see and react to the confirmation.
        setTimeout(() => {
            btn.textContent = orig;
            btn.classList.remove('copied');
            btn.disabled = false;
        }, 3500);
    }).catch(() => {
        btn.textContent = orig;
        btn.disabled = false;
        Toast.error('Copy failed — please select the key and press Ctrl/Cmd+C manually', 8000);
    });
};

// Flip the post-creation modal's hero status from "save it now" to a
// persistent green "saved" badge so the user has confirmation even after
// the Copy button label reverts. Idempotent — safe to call repeatedly.
App._markKeyModalAsSaved = function() {
    const dot = document.getElementById('apkm-hero-dot');
    const sub = document.getElementById('apkm-hero-sub');
    const hero = document.getElementById('apkm-hero-status');
    if (!dot || !sub || !hero) return;
    dot.style.background = '#22c55e';
    dot.style.boxShadow = '0 0 8px rgba(34, 197, 94, 0.7)';
    sub.innerHTML = '<strong>Saved to clipboard.</strong> You can safely close this dialog or click <em>Manage Keys</em> to continue.';
    hero.classList.add('apkm-hero--saved');
};

// Offer a .env download so the user can save the key without copy/paste friction.
App._downloadKeyFile = function(fullKey, name) {
    const safeName = String(name || 'worker-key').replace(/[^a-z0-9_-]+/gi, '-').toLowerCase() || 'worker-key';
    const body = `# Phonos worker credentials — keep this file secret.\n` +
        `# Generated: ${new Date().toISOString()}\n` +
        `WORKER_API_KEY=${fullKey}\n` +
        `PHONOS_BRIDGE_URL=${window.location.origin}/api/bridge/v1\n`;
    const blob = new Blob([body], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${safeName}.env`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    Toast.success('Key file downloaded — move it out of your downloads folder', 8000);
    App._markKeyModalAsSaved();
};

// Test the freshly created worker key against the bridge by calling
// /api/bridge/v1/worker/info with a Bearer header. Reports models + projects
// the key is authorized for so the user gets immediate confirmation.
App._testWorkerConnection = async function(modelId, fullKey) {
    const resultEl = document.getElementById('apkm-test-result');
    if (!resultEl) return;

    resultEl.className = 'apkm-test-result pending';
    resultEl.innerHTML = '<span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:#3b82f6;margin-right:6px;vertical-align:middle;animation:pulse 1s infinite;"></span>Testing connection…';

    try {
        const resp = await fetch('/api/bridge/v1/worker/info', {
            method: 'GET',
            headers: {
                'Authorization': 'Bearer ' + fullKey,
                'Accept': 'application/json'
            },
            credentials: 'same-origin'
        });
        const data = await resp.json().catch(() => ({}));

        if (resp.ok && data.status === 'success') {
            const models = data.authorized_models || [];
            const projects = data.authorized_projects || [];
            const rate = data.rate_limit ? `${data.rate_limit}/min` : '—';
            const modelNames = models.map(m => `${m.name} <span style="opacity:0.6;font-size:10px;">#${m.id}</span>`).join(', ') || 'none';
            const projectNames = projects.map(p => `${p.name} <span style="opacity:0.6;font-size:10px;">#${p.id}</span>`).join(', ') || 'none';

            resultEl.className = 'apkm-test-result ok';
            resultEl.innerHTML = [
                '<div style="font-weight:700;margin-bottom:8px;">✓ Connection successful — key authenticated.</div>',
                '<div style="display:grid;grid-template-columns:auto 1fr;gap:6px 12px;font-size:11px;">',
                '  <div style="opacity:0.7;">Rate limit</div><div>' + escapeHtml(rate) + '</div>',
                '  <div style="opacity:0.7;">Models</div><div>' + modelNames + '</div>',
                '  <div style="opacity:0.7;">Projects</div><div>' + projectNames + '</div>',
                '</div>'
            ].join('');
            Toast.success('Connection test passed — worker is authorized', 6000);
        } else {
            const msg = (data && (data.message || data.error)) || ('HTTP ' + resp.status);
            resultEl.className = 'apkm-test-result err';
            resultEl.innerHTML = '<strong>✗ Test failed</strong><br><span style="font-size:11px;">' + escapeHtml(msg) + '</span>';
            Toast.error('Connection test failed: ' + msg, 8000);
        }
    } catch (err) {
        resultEl.className = 'apkm-test-result err';
        resultEl.innerHTML = '<strong>✗ Network error</strong><br><span style="font-size:11px;">' + escapeHtml(err.message || String(err)) + '</span>';
        Toast.error('Connection test failed: ' + (err.message || err), 8000);
    }
};

// Update the schema field count badge in the builder
App._updateSchemaFieldCount = function() {
    const badge = document.getElementById('schema-field-count');
    if (!badge) return;
    const count = document.querySelectorAll('#schema-fields-list .schema-field-item').length;
    badge.textContent = (window.i18n ? window.i18n.t('app.nFields').replace('{n}', count) : count + (count === 1 ? ' field' : ' fields'));
};

App.deleteUserModel = async function(modelId) {
    const confirmed = await Modal.confirm({
        title: window.i18n ? window.i18n.t('app.deleteUserModelTitle') : 'Delete User Model',
        message: window.i18n ? window.i18n.t('app.deleteUserModelMessage') : 'Are you sure you want to delete this model? This action cannot be undone. All associated API keys and job history will be preserved but the model will no longer accept new jobs.',
        confirmText: window.i18n ? window.i18n.t('app.delete') : 'Delete',
        confirmClass: 'btn-error'
    });

    if (!confirmed) return;

    try {
        await API.delete(`/api/user-models/${modelId}`);
        Toast.success(window.i18n ? window.i18n.t('app.modelDeleted') : 'Model deleted successfully');
        Views.load('user-models');
    } catch (error) {
        Toast.error(error.message || (window.i18n ? window.i18n.t('app.failedToDeleteModel') : 'Failed to delete model'));
    }
};

